o se resuelven.","tree":{"sha":"f4cf388b7cf217a652923a5dc27109ca6203f6a1","url":"https://api.github.com/repos/equipo2-AgroSmart-Insights/Agrosmart-Insights/git/trees/f4cf388b7cf217a652923a5dc27109ca6203f6a1"},"url":"https://api.github.com/repos/equipo2-AgroSmart-Insights/Agrosmart-Insights/git/commits/5e0a983d7022370144c81e6525ce25e25675f628","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/147784263?v=4","events_url":"https://api.github.com/users/GabouLC/events{/privacy}","followers_url":"https://api.github.com/users/GabouLC/followers","following_url":"https://api.github.com/users/GabouLC/following{/other_user}","gists_url":"https://api.github.com/users/GabouLC/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/GabouLC","id":147784263,"login":"GabouLC","node_id":"U_kgDOCM8CRw","organizations_url":"https://api.github.com/users/GabouLC/orgs","received_events_url":"https://api.github.com/users/GabouLC/received_events","repos_url":"https://api.github.com/users/GabouLC/repos","site_admin":false,"starred_url":"https://api.github.com/users/GabouLC/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/GabouLC/subscriptions","type":"User","url":"https://api.github.com/users/GabouLC","user_view_type":"public"},"html_url":"https://github.com/equipo2-AgroSmart-Insights/Agrosmart-Insights/commit/5e0a983d7022370144c81e6525ce25e25675f628","node_id":"C_kwDOTxyiy9oAKDVlMGE5ODNkNzAyMjM3MDE0NGM4MWU2NTI1Y2UyNWUyNTY3NWY2Mjg","parents":[{"html_url":"https://github.com/equipo2-AgroSmart-Insights/Agrosmart-Insights/commit/f5591096ebdad301c0344a4200960d26008b4542","sha":"f5591096ebdad301c0344a4200960d26008b4542","url":"https://api.github.com/repos/equipo2-AgroSmart-Insights/Agrosmart-Insights/commits/f5591096ebdad301c0344a4200960d26008b4542"}],"sha":"5e0a983d7022370144c81e6525ce25e25675f628","url":"https://api.github.com/repos/equipo2