INSERT INTO collection_pages VALUES('6b1d686e1c29ba7b7661561655dbe2371c82916b5e6e9aae8f8be7742263876e','c6b3a6ed06964f4a8c7769a28acc0db0c674813aa867dcf171ac5af42d399bec','{"hasNext":false,"items":[{"author":{"account":{"login":"Tamilarasubotminds","providerType":"User"},"email":"tamilarasu@botminds.ai","name":"tamilarasu"},"authoredDate":"2026-08-08T06:22:53Z","committedDate":"2026-08-08T06:22:53Z","committer":{"account":{"login":"Tamilarasubotminds","providerType":"User"},"email":"tamilarasu@botminds.ai","name":"tamilarasu"},"observedAt":"2026-10-09T00:06:48.744Z","repositoryId":1327459369,"sha":"2e924d7bb4f68fdc5cb48f1059c4b4f7ef7cae0a"},{"author":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"authoredDate":"2026-08-07T03:42:22Z","committedDate":"2026-08-07T03:42:22Z","committer":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"observedAt":"2026-10-09T00:06:48.744Z","repositoryId":1327459369,"sha":"f3e2c5db361ee04196b9ce9eb8349978cd9adb98"},{"author":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"authoredDate":"2026-08-06T16:27:31Z","committedDate":"2026-08-06T16:27:31Z","committer":{"account":{"login":"claude","providerType":"User"},"email":"noreply@anthropic.com","name":"Claude"},"observedAt":"2026-10-09T00:06:48.744Z","repositoryId":1327459369,"sha":"26485c06b226b17c808fd5c3921bffdc50d10b2e"}],"observedAt":"2026-10-09T00:06:48.744Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/229270046?v=4","events_url":"https://api.github.com/users/Tamilarasubotminds/events{/privacy}","followers_url":"https://api.github.com/users/Tamilarasubotminds/followers","following_url":"https://api.github.com/users/Tamilarasubotminds/following{/other_user}","gists_url":"https://api.github.com/users/Tamilarasubotminds/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Tamilarasubotminds","id":229270046,"login":"Tamilarasubotminds","node_id":"U_kgDODapiHg","organizations_url":"https://api.github.com/users/Tamilarasubotminds/orgs","received_events_url":"https://api.github.com/users/Tamilarasubotminds/received_events","repos_url":"https://api.github.com/users/Tamilarasubotminds/repos","site_admin":false,"starred_url":"https://api.github.com/users/Tamilarasubotminds/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Tamilarasubotminds/subscriptions","type":"User","url":"https://api.github.com/users/Tamilarasubotminds","user_view_type":"public"},"comments_url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/commits/2e924d7bb4f68fdc5cb48f1059c4b4f7ef7cae0a/comments","commit":{"author":{"date":"2026-08-08T06:22:53Z","email":"tamilarasu@botminds.ai","name":"tamilarasu"},"comment_count":0,"committer":{"date":"2026-08-08T06:22:53Z","email":"tamilarasu@botminds.ai","name":"tamilarasu"},"message":"Add PWA support and link the live site in the README\n\nMakes the site installable and usable offline, which suits revising on a\ncommute more than a browser tab does.\n\nThe service worker is hand-written rather than generated: a static export\nhas no server to negotiate freshness with, so the strategy falls out of\nwhat each response is. /_next/static/* is content-hashed and therefore\nimmutable (cache first), HTML changes on every deploy (network first,\ncached as the offline copy), and anything never visited falls back to\n/offline/.\n\nOnly the entry points are precached. Seeding all 229 question pages would\ncost megabytes for pages most people never open, so each is cached the\nfirst time it is actually read.\n\nRegistration is production-only — under `next dev` the worker caches\nmodules the dev server is still rebuilding.\n\nIcons are rendered from react-icon.svg; the maskable pair keeps its\nartwork inside the middle 80% so Android''s adaptive mask cannot crop it.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"80f31a00fc7df0653f276b5784bb02c10368840e","url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/git/trees/80f31a00fc7df0653f276b5784bb02c10368840e"},"url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/git/commits/2e924d7bb4f68fdc5cb48f1059c4b4f7ef7cae0a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/229270046?v=4","events_url":"https://api.github.com/users/Tamilarasubotminds/events{/privacy}","followers_url":"https://api.github.com/users/Tamilarasubotminds/followers","following_url":"https://api.github.com/users/Tamilarasubotminds/following{/other_user}","gists_url":"https://api.github.com/users/Tamilarasubotminds/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Tamilarasubotminds","id":229270046,"login":"Tamilarasubotminds","node_id":"U_kgDODapiHg","organizations_url":"https://api.github.com/users/Tamilarasubotminds/orgs","received_events_url":"https://api.github.com/users/Tamilarasubotminds/received_events","repos_url":"https://api.github.com/users/Tamilarasubotminds/repos","site_admin":false,"starred_url":"https://api.github.com/users/Tamilarasubotminds/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Tamilarasubotminds/subscriptions","type":"User","url":"https://api.github.com/users/Tamilarasubotminds","user_view_type":"public"},"html_url":"https://github.com/tamilarasu18/React-Interview-Prep/commit/2e924d7bb4f68fdc5cb48f1059c4b4f7ef7cae0a","node_id":"C_kwDOTx9sKdoAKDJlOTI0ZDdiYjRmNjhmZGM1Y2I0OGYxMDU5YzRiNGY3ZWY3Y2FlMGE","parents":[{"html_url":"https://github.com/tamilarasu18/React-Interview-Prep/commit/f3e2c5db361ee04196b9ce9eb8349978cd9adb98","sha":"f3e2c5db361ee04196b9ce9eb8349978cd9adb98","url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/commits/f3e2c5db361ee04196b9ce9eb8349978cd9adb98"}],"sha":"2e924d7bb4f68fdc5cb48f1059c4b4f7ef7cae0a","url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/commits/2e924d7bb4f68fdc5cb48f1059c4b4f7ef7cae0a"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"comments_url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/commits/f3e2c5db361ee04196b9ce9eb8349978cd9adb98/comments","commit":{"author":{"date":"2026-08-07T03:42:22Z","email":"noreply@anthropic.com","name":"Claude"},"comment_count":0,"committer":{"date":"2026-08-07T03:42:22Z","email":"noreply@anthropic.com","name":"Claude"},"message":"Add 116 questions covering the rest of a senior interview loop\n\nv1.0 covered the React concepts round well but was only one of the four\nor five rounds a 4+ year candidate actually faces. This fills the gaps,\ntaking the collection from 113 to 229 questions.\n\nNew categories:\n\n- Machine Coding (24) — build-it challenges where shortAnswer becomes the\n  approach you state before typing: debounce, throttle, typeahead, infinite\n  scroll, virtualised list, focus-trapped modal, drag-and-drop, wizard,\n  data table, toasts, tabs, carousel, useFetch, Promise.all, memoize,\n  deep clone, LRU cache, URL-synced search\n- Frontend System Design (16) — feed, chat, e-commerce, dashboard,\n  offline-first, uploads, design systems, gallery, collaborative editing,\n  notifications, caching, i18n, feature flags, plus how to run the round\n- Security & Auth (16) — token storage, JWT vs sessions, XSS, CSRF,\n  OAuth/PKCE, refresh races, CORS, CSP, secrets, RBAC, headers,\n  supply chain, clickjacking, payments, iframes\n- Architecture at Scale (16) — folder structure, monorepos,\n  micro-frontends, migrations, observability, bundle budgets, CI/CD,\n  API contracts, build-vs-buy, code quality, deploy safety, tech debt\n- DSA (28) — the patterns that actually appear in frontend loops, in\n  JavaScript, with complexity trade-offs stated rather than assumed\n- Behavioral & Experience (16) — answer structures and what interviewers\n  listen for, not scripts to recite\n\nNo schema change: the three-layer format adapted to all six categories.\nFor a coding round shortAnswer is the approach; for behavioural it is the\nstructure. One schema keeps flashcards and the cheat sheet uniform.\n\nAlso fixes two validator false positives — shell comments and closing\nfences inside code blocks were being read as H1s and unlabelled blocks.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"84c16bda04e3ee9754bbeabc52ab0af97c30a5b0","url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/git/trees/84c16bda04e3ee9754bbeabc52ab0af97c30a5b0"},"url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/git/commits/f3e2c5db361ee04196b9ce9eb8349978cd9adb98","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"html_url":"https://github.com/tamilarasu18/React-Interview-Prep/commit/f3e2c5db361ee04196b9ce9eb8349978cd9adb98","node_id":"C_kwDOTx9sKdoAKGYzZTJjNWRiMzYxZWUwNDE5NmI5Y2U5ZWI4MzQ5OTc4Y2Q5YWRiOTg","parents":[{"html_url":"https://github.com/tamilarasu18/React-Interview-Prep/commit/26485c06b226b17c808fd5c3921bffdc50d10b2e","sha":"26485c06b226b17c808fd5c3921bffdc50d10b2e","url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/commits/26485c06b226b17c808fd5c3921bffdc50d10b2e"}],"sha":"f3e2c5db361ee04196b9ce9eb8349978cd9adb98","url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/commits/f3e2c5db361ee04196b9ce9eb8349978cd9adb98"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/81847?v=4","events_url":"https://api.github.com/users/claude/events{/privacy}","followers_url":"https://api.github.com/users/claude/followers","following_url":"https://api.github.com/users/claude/following{/other_user}","gists_url":"https://api.github.com/users/claude/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/claude","id":81847,"login":"claude","node_id":"MDQ6VXNlcjgxODQ3","organizations_url":"https://api.github.com/users/claude/orgs","received_events_url":"https://api.github.com/users/claude/received_events","repos_url":"https://api.github.com/users/claude/repos","site_admin":false,"starred_url":"https://api.github.com/users/claude/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/claude/subscriptions","type":"User","url":"https://api.github.com/users/claude","user_view_type":"public"},"comments_url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/commits/26485c06b226b17c808fd5c3921bffdc50d10b2e/comments","commit":{"author":{"date":"2026-08-06T16:27:31Z","email":"noreply@anthropic.com","name":"Claude"},"comment_count":0,"committer":{"date":"2026-08-06T16:27:31Z","email":"noreply@anthropic.com","name":"Claude"},"message":"Initial release: React interview prep site\n\n113 React interview questions across 14 categories, structured for\nmemorisation rather than reading. Every question carries three layers:\na spoken short answer, a memory hook, and a full explanation.\n\nBuilt on the same stack as flutter-interview-prep (Next.js 15 App Router,\nstatic export, TypeScript, Tailwind), with additions aimed at recall:\n\n- Flashcard mode: shuffle, filter by category and difficulty, track known\n  cards in localStorage, keyboard shortcuts\n- Printable cheat sheet of every short answer and memory hook\n- Recall-first question cards that hide the answer until tapped\n\nContent lives as one JSON file per topic under data/questions/ and is\ncompiled by scripts/build-questions.js, which derives category counts and\nfails on duplicate ids or unknown categories. scripts/validate-questions.js\nenforces the short-answer and memory-hook length limits that keep the\nformat speakable.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>","tree":{"sha":"89e338275d1bf827e87c7d68b7919dc9ebb9451c","url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/git/trees/89e338275d1bf827e87c7d68b7919dc9ebb9451c"},"url":"https://api.github.com/repos/tamilarasu18/React-Interview-Prep/git/commits/26485c06b226b17c808fd5c3921bffdc50d10b2e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"ava